#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

int main() {
    int n;
    scanf("%d", &n);
    vector<pair<ll, ll>> iv(n);
    bool single = false;
    for (auto &[l, r] : iv) {
        scanf("%lld %lld", &l, &r);
        if (l == r) single = true;
    }
    if (single) {
        puts("-1");
        return 0;
    }
    // Right endpoint ascending, left endpoint descending on ties.
    sort(iv.begin(), iv.end(), [](auto &x, auto &y) {
        return x.second != y.second ? x.second < y.second : x.first > y.first;
    });
    ll a = -1, b = -1, answer = 0;  // the two largest chosen numbers, a < b
    for (auto &[l, r] : iv) {
        if (l > b) a = r - 1, b = r, answer += 2;
        else if (l > a) a = b, b = r, answer += 1;
    }
    printf("%lld\n", answer);
}

import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int s = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, s, pos - s);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = nextInt();
        long[] key = new long[n];
        boolean single = false;
        // Sort key: right endpoint ascending, then left endpoint descending (both < 2^30).
        for (int i = 0; i < n; i++) {
            long l = nextLong(), r = nextLong();
            if (l == r) single = true;
            key[i] = r << 31 | ((1L << 31) - 1 - l);
        }
        if (single) {
            System.out.println(-1);
            return;
        }
        Arrays.sort(key);
        long a = -1, b = -1, answer = 0; // the two largest chosen numbers, a < b
        for (long k : key) {
            long r = k >>> 31, l = (1L << 31) - 1 - (k & ((1L << 31) - 1));
            if (l > b) {
                a = r - 1;
                b = r;
                answer += 2;
            } else if (l > a) {
                a = b;
                b = r;
                answer += 1;
            }
        }
        System.out.println(answer);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
	"sort"
)

var data []byte
var p int

func next() []byte {
	for p < len(data) && data[p] <= ' ' {
		p++
	}
	s := p
	for p < len(data) && data[p] > ' ' {
		p++
	}
	return data[s:p]
}

func nextInt() int64 {
	t := next()
	neg := len(t) > 0 && t[0] == '-'
	if neg {
		t = t[1:]
	}
	var r int64
	for _, c := range t {
		r = r*10 + int64(c-'0')
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := int(nextInt())
	L := make([]int64, n)
	R := make([]int64, n)
	single := false
	for i := 0; i < n; i++ {
		L[i], R[i] = nextInt(), nextInt()
		if L[i] == R[i] {
			single = true
		}
	}
	if single {
		fmt.Println(-1)
		return
	}
	ord := make([]int, n)
	for i := range ord {
		ord[i] = i
	}
	// Right endpoint ascending, left endpoint descending on ties.
	sort.Slice(ord, func(x, y int) bool {
		p, q := ord[x], ord[y]
		if R[p] != R[q] {
			return R[p] < R[q]
		}
		return L[p] > L[q]
	})
	var a, b, answer int64 = -1, -1, 0 // the two largest chosen numbers, a < b
	for _, i := range ord {
		l, r := L[i], R[i]
		if l > b {
			a, b = r-1, r
			answer += 2
		} else if l > a {
			a, b = b, r
			answer++
		}
	}
	fmt.Println(answer)
}
